<script lang="ts">
  import {refreshAll} from '$app/navigation';import {focusTrap} from '#lib/client/focus-trap.ts';import {command,display,recordName} from '#lib/client/api.ts';import type {AppData,Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import DataPreview from './DataPreview.svelte';import ImportRowEditor from './ImportRowEditor.svelte';
  let {data}:{data:AppData}=$props();let selected:string[]=$state([]);let group=$state('');let confirm=$state(false);let understood=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');let editing:Row|null=$state(null);let rowProduct=$state('');let rowAmount=$state('');let rowBasis=$state('');let rowUnit=$state('piece');let rowCurrency=$state('EUR');let rowType=$state('customers');let rowData:Row=$state({});
  const rowTypes=$derived(data.summary?.importRowTypes||[{value:'customers',label:'Kunde'},{value:'suppliers',label:'Lieferant'},{value:'products',label:'Produkt'},{value:'historical_documents',label:'Historisches Original'}]);
  const price=$derived(data.module?.slug==='price-imports');const rows=$derived(data.related?.price_import_rows||data.related?.staging_records||data.related?.import_rows||data.related?.rows||[]);const filtered=$derived(rows.filter(r=>!group||category(r)===group));const chosen=$derived(rows.filter(r=>selected.includes(r.id)));const canCommit=$derived(data.detail?.status==='needs_review');
  function category(row:Row){if(row.errors?.length||['invalid','error','failed'].includes(row.status))return 'error';if(row.match_status==='missing'||row.status==='missing')return 'missing';if(row.match_status==='new'||row.status==='new')return 'new';if(row.requires_review||row.match_status==='uncertain'||row.status==='needs_review')return 'review';return 'matched';}
  function priceAmount(value:any,currency?:string){if(value===undefined||value===null||value==='')return '—';const amount=Number(String(value).replace(',','.'));if(!Number.isFinite(amount))return '—';if(currency){try{return new Intl.NumberFormat('de-DE',{style:'currency',currency}).format(amount);}catch{/* Keep an unrecognised source currency visible for review. */}}return new Intl.NumberFormat('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(amount)+' · '+(currency||'Währung offen');}
  const categories=[{id:'',label:'Alle Zeilen'},{id:'matched',label:'Sicher zugeordnet'},{id:'review',label:'Prüfen'},{id:'new',label:'Neu'},{id:'missing',label:'Nicht mehr gelistet'},{id:'error',label:'Fehlerhaft'}];
  function toggle(row:Row,checked:boolean){selected=checked?[...new Set([...selected,row.id])]:selected.filter(id=>id!==row.id);}
  function editRow(row:Row){editing=row;rowProduct=row.product_id||'';rowAmount=row.amount??row.new_price??'';rowBasis=row.basis_quantity??'';rowUnit=row.unit||'piece';rowCurrency=row.currency||'';rowType=row.entity_type||'customers';rowData=JSON.parse(JSON.stringify(row.data||row.normalized_data||row.proposed_data||{}));error='';}
  async function saveRow(event:SubmitEvent){event.preventDefault();if(!editing)return;busy=true;error='';try{const payload=price?{product_id:rowProduct,amount:rowAmount,basis_quantity:rowBasis,unit:rowUnit,currency:rowCurrency}:{entity_type:rowType,data:Object.fromEntries(Object.entries(rowData).filter(([,value])=>value!==''))};await command(price?'catalog.price_import.row.update':'migration.import.row.update',editing.id,payload,editing.version);editing=null;notice='Die Zeile wurde geprüft gespeichert. Wählen Sie sie anschließend ausdrücklich für die Übernahme aus.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Prüfzeile konnte nicht gespeichert werden.';}finally{busy=false;}}
  async function apply(event:SubmitEvent){event.preventDefault();if(!chosen.length||!understood||busy)return;busy=true;error='';try{await command(price?'catalog.price_import.approve':'migration.import.commit',data.detail?.id,{row_ids:chosen.map(r=>r.id)},data.detail?.version);notice=price?'Die ausgewählten Preiszeilen wurden atomar freigegeben. Bestehende Belege behalten ihren Preisstand.':'Die geprüften Zeilen wurden in den Betriebsbestand übernommen. Die Herkunft bleibt nachvollziehbar.';selected=[];confirm=false;await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Freigabe konnte nicht übernommen werden. Prüfen Sie die Zeilen und den aktuellen Stand.';}finally{busy=false;}}
</script>
<section class="panel"><header class="panel-header"><div><h2>{price?'Preisvergleich & Quellenprüfung':'Importvorschau & Zuordnung'}</h2><p>{price?'Prüfen Sie den neuen Preisstand zeilenweise vor der Aktivierung.':'Nur ausdrücklich ausgewählte und fachlich zulässige Zeilen werden übernommen.'}</p></div><span class="count">{rows.length}</span></header><div class="panel-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}<div class="subnav" aria-label="Zeilengruppen">{#each categories as category}<button class="btn small" class:primary={group===category.id} onclick={()=>group=category.id}>{category.label}{#if category.id}<span class="count">{rows.filter(r=>category.id===(r.errors?.length?'error':r.match_status||r.status)).length}</span>{/if}</button>{/each}</div>{#if rows.length}<div class="table-scroll"><table class="data-table"><thead><tr><th>Prüfen</th><th>{price?'Artikel / konkrete Variante':'Datensatz'}</th>{#if price}<th class="number">Bisher</th><th class="number">Neu</th><th>Preisbasis</th>{:else}<th>Vorgeschlagene Daten</th>{/if}<th>Quelle</th><th>Status / Hinweise</th><th>Bearbeiten</th></tr></thead><tbody>{#each filtered as row}<tr><td><input type="checkbox" checked={selected.includes(row.id)} onchange={(e)=>toggle(row,e.currentTarget.checked)} aria-label={`${row.name||row.description||row.source_row||'Zeile'} zur Freigabe auswählen`} disabled={!canCommit||category(row)==='error'||category(row)==='missing'}/></td><td><strong>{row.name||row.description||row.article_number||row.supplier_sku||row.source_id||`Zeile ${row.row_number||row.source_row||'—'}`}</strong>{#if row.product_variant_id}<p class="record-subtitle">Variante {display(row.product_variant_id,'product_variant_id',data)}</p>{/if}</td>{#if price}<td class="number">{priceAmount(row.old_price??row.previous_price,row.old_currency||row.previous_currency)}</td><td class="number">{priceAmount(row.amount??row.new_price??row.unit_price??row.price,row.currency)}</td><td>{row.basis_quantity||row.price_basis_quantity||'—'} {row.price_basis_unit||row.unit||'—'}<br/><span class="muted">{row.currency||'—'} · {row.valid_from?display(row.valid_from,'valid_from'):'Gültigkeit offen'}</span></td>{:else}<td><details><summary style="cursor:pointer;font-size:11px">Vorschau ansehen</summary><DataPreview value={row.normalized_data||row.proposed_data||row.data||row.payload||{}} {data}/></details></td>{/if}<td>{row.source_locator||row.source_cell||row.source_page||row.row_number||row.source_row||'—'}</td><td><Status value={category(row)==='error'?'failed':category(row)==='review'?'needs_review':row.status||'needs_review'}/>{#if row.errors?.length}<p class="record-subtitle">{row.errors.map((e:any)=>typeof e==='string'?e:e.message||e.code).join(' · ')}</p>{/if}{#if row.warnings?.length}<p class="record-subtitle">{row.warnings.map((e:any)=>typeof e==='string'?e:e.message||e.code).join(' · ')}</p>{/if}</td><td>{#if canCommit}<button class="btn small" onclick={()=>editRow(row)}><Icon name="edit" size={13}/>Prüfen</button>{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="empty-state compact"><div class="empty-icon"><Icon name="file"/></div><h3>Noch keine prüfbaren Zeilen</h3><p>Starten Sie die Dateianalyse oder das Staging. Fehlende Dateiprüfung, Parser oder Quellangaben werden im Verarbeitungsstatus ausgewiesen.</p></div>{/if}{#if rows.length}<div class="inline-actions mt"><button class="btn primary" disabled={!selected.length||!canCommit} onclick={()=>{confirm=true;understood=false;}}>{selected.length} Zeile(n) zur Freigabe prüfen<Icon name="arrow" size={16}/></button><button class="btn" disabled={!selected.length} onclick={()=>selected=[]}>Auswahl aufheben</button></div><p class="field-help mt">Fehlerhafte oder nicht mehr gelistete Zeilen werden nicht still übernommen. Ein neuer Preis ändert keine bereits angenommene Vereinbarung.</p>{/if}</div></section>
{#if confirm}<div class="modal-backdrop" role="presentation"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="import-confirm-title" tabindex="-1" use:focusTrap onkeydown={(e)=>{if(e.key==='Escape'&&!busy)confirm=false;}}><header class="modal-header"><div><h2 id="import-confirm-title">{price?'Ausgewählten Preisstand aktivieren':'Geprüfte Zeilen übernehmen'}</h2><p>{recordName(data.detail)} · Version {data.detail?.version} · {chosen.length} ausdrücklich ausgewählte Zeilen</p></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={()=>confirm=false}><Icon name="close"/></button></header><form onsubmit={apply} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#each chosen as row}<div class="action-preview"><h3>{row.name||row.description||row.article_number||`Zeile ${row.row_number||'—'}`}</h3>{#if price}<p class="small">Bisher {priceAmount(row.old_price??row.previous_price,row.old_currency||row.previous_currency)} → Neu {priceAmount(row.amount??row.new_price??row.unit_price??row.price,row.currency)} · {row.basis_quantity||row.price_basis_quantity||'—'} {row.price_basis_unit||row.unit||'—'}</p>{:else}<DataPreview value={row.normalized_data||row.proposed_data||row.data||row.payload||{}} {data}/>{/if}<p class="field-help mt">Quelle {row.source_locator||row.source_cell||row.source_page||row.row_number||'nicht angegeben'}</p></div>{/each}<label class="check-field"><input type="checkbox" bind:checked={understood} required/><span>Ich habe Herkunft, Zuordnung, Einheiten, Gültigkeit und die angezeigten Änderungen für alle ausgewählten Zeilen geprüft.</span></label></div><footer class="modal-footer"><button class="btn" type="button" onclick={()=>confirm=false} disabled={busy}>Zurück</button><button class="btn primary" disabled={busy||!understood}>{busy?'Wird übernommen …':price?'Geprüfte Preise aktivieren':'Geprüfte Zeilen übernehmen'}</button></footer></form></div></div>{/if}

{#if editing}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="row-edit-title" tabindex="-1" use:focusTrap><header class="modal-header"><div><h2 id="row-edit-title">Prüfzeile bearbeiten</h2><p>Zeile {editing.row_number||'—'} · Quelle {editing.source_locator||'nicht angegeben'} · Version {editing.version}</p></div><button class="icon-button" aria-label="Schließen" onclick={()=>editing=null} disabled={busy}><Icon name="close"/></button></header><form onsubmit={saveRow} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<div class="field-grid">{#if price}<div class="field full"><label for="review-product">Genaue Produktzuordnung *</label>{#if data.lookups?.products?.length}<select id="review-product" bind:value={rowProduct} required><option value="">Produkt wählen</option>{#each data.lookups.products as product}<option value={product.id}>{product.name}</option>{/each}</select>{:else}<input id="review-product" bind:value={rowProduct} required/><span class="field-help">ID des geprüften Produkts. Öffnen Sie die <a class="text-link" href="/products" target="_blank">Produktliste</a> zur Zuordnung.</span>{/if}</div><div class="field"><label for="review-price">Neuer Preis *</label><input id="review-price" bind:value={rowAmount} inputmode="decimal" required/></div><div class="field"><label for="review-basis">Preisbasismenge *</label><input id="review-basis" bind:value={rowBasis} inputmode="decimal" required/></div><div class="field"><label for="review-unit">Preiseinheit *</label><select id="review-unit" bind:value={rowUnit}><option value="piece">Stück</option><option value="mm">mm</option><option value="m">m</option><option value="m2">m²</option><option value="m3">m³</option><option value="kg">kg</option><option value="h">Stunde</option><option value="day">Tag</option><option value="package">Pauschale</option></select></div><div class="field"><label for="review-currency">Währung *</label><input id="review-currency" bind:value={rowCurrency} minlength="3" maxlength="3" required/></div>{:else}<div class="field full"><label for="review-type">Datensatzart *</label><select id="review-type" bind:value={rowType}>{#each rowTypes as type}<option value={type.value}>{type.label}</option>{/each}</select></div><ImportRowEditor kind={rowType} bind:value={rowData} {data}/>{/if}</div></div><footer class="modal-footer"><button type="button" class="btn" onclick={()=>editing=null} disabled={busy}>Abbrechen</button><button class="btn primary" disabled={busy}>{busy?'Wird geprüft …':'Zeile geprüft speichern'}</button></footer></form></div></div>{/if}
